WITH qualified AS (SELECT b.mktcode,b.tgtcode FROM `newzl`.`hsj_stock_hq_basic` AS b WHERE b.mktcode=1 AND b.bizdate IN ('2026-04-14','2026-04-13','2026-04-10','2026-04-09','2026-04-08') GROUP BY b.mktcode,b.tgtcode HAVING MIN(b.volume) > 1000000) SELECT a.mktcode,a.tgtcode,a.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS a INNER JOIN qualified AS q ON q.mktcode=a.mktcode AND q.tgtcode=a.tgtcode WHERE a.bizdate='2026-04-14';
